/* Same security decision as the live receiver 'WhatsApp Cloud - Inbound
 * Receiver (Meta)', node 'Verify Or Refuse'. Kept byte-identical in its HMAC
 * core on purpose: a second, weaker verifier on a second endpoint is how a
 * signed-origin guarantee quietly stops being one.
 *
 *  1. Meta signs the EXACT BYTES it sent. Re-serialising the JSON to hash gives
 *     different bytes for any non-ASCII name.
 *  2. With no app secret configured this endpoint REFUSES. A dormant gate is an
 *     open door.
 *  3. The HMAC is implemented in full because this Code sandbox has neither
 *     require('crypto') nor the WebCrypto global.
 *
 * This node writes NOTHING and it does not record the channel event -- the live
 * receiver owns that. This endpoint only reads the signed metadata.
 */
const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];

function sha256(bytes) {
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
             0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const l = bytes.length;
  const buf = new Uint8Array((((l + 8) >> 6) + 1) << 6);
  buf.set(bytes); buf[l] = 0x80;
  const dv = new DataView(buf.buffer), bits = l * 8;
  dv.setUint32(buf.length - 8, Math.floor(bits / 4294967296));
  dv.setUint32(buf.length - 4, bits >>> 0);
  const w = new Uint32Array(64);
  for (let off = 0; off < buf.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const x = w[i - 15], y = w[i - 2];
      const s0 = ((x >>> 7) | (x << 25)) ^ ((x >>> 18) | (x << 14)) ^ (x >>> 3);
      const s1 = ((y >>> 17) | (y << 15)) ^ ((y >>> 19) | (y << 13)) ^ (y >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32), odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i]);
  return out;
}

function hmacHex(keyBytes, msgBytes) {
  const k = keyBytes.length > 64 ? sha256(keyBytes) : keyBytes;
  const ipad = new Uint8Array(64), opad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) {
    const kb = i < k.length ? k[i] : 0;
    ipad[i] = kb ^ 0x36; opad[i] = kb ^ 0x5c;
  }
  const inner = new Uint8Array(64 + msgBytes.length);
  inner.set(ipad); inner.set(msgBytes, 64);
  const outer = new Uint8Array(96);
  outer.set(opad); outer.set(sha256(inner), 64);
  return Array.from(sha256(outer)).map(b => b.toString(16).padStart(2, '0')).join('');
}

const item = $input.first();
const j = item.json || {};
const headers = j.headers || {};
const query = j.query || {};
const VERIFY_TOKEN = String($env.META_WEBHOOK_VERIFY_TOKEN || '');
const APP_SECRET = String($env.META_APP_SECRET || '');

const refuse = (status, code, why) => [{ json: {
  verdict: 'REFUSE', respond_status: status, respond_text: code,
  reason_code: code, why, wrote_nothing: true } }];

const sameString = (a, b) => {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
};

if (query['hub.mode'] !== undefined || query['hub.challenge'] !== undefined) {
  if (!VERIFY_TOKEN) {
    return refuse(500, 'VERIFY_TOKEN_NOT_CONFIGURED',
      'META_WEBHOOK_VERIFY_TOKEN is unset on this box.');
  }
  if (String(query['hub.mode']) !== 'subscribe') {
    return refuse(400, 'HUB_MODE_NOT_SUBSCRIBE', 'hub.mode was not subscribe.');
  }
  if (!sameString(String(query['hub.verify_token'] || ''), VERIFY_TOKEN)) {
    return refuse(403, 'HUB_VERIFY_TOKEN_MISMATCH', 'The verify token did not match.');
  }
  return [{ json: {
    verdict: 'CHALLENGE', respond_status: 200,
    respond_text: String(query['hub.challenge'] || ''),
    reason_code: 'SUBSCRIPTION_CONFIRMED', wrote_nothing: true } }];
}

if (!APP_SECRET) {
  return refuse(500, 'APP_SECRET_NOT_CONFIGURED',
    'META_APP_SECRET is unset on this box, so no delivery can be verified. ' +
    'Refusing every request until it is set - this gate is never dormant.');
}

let raw = null, raw_source = null;
const bin = item.binary && (item.binary.data || item.binary.body);
if (bin && bin.data) { raw = Buffer.from(bin.data, 'base64'); raw_source = 'binary'; }
else if (typeof j.body === 'string') { raw = Buffer.from(j.body, 'utf8'); raw_source = 'string'; }
if (!raw) {
  return refuse(500, 'RAW_BODY_NOT_AVAILABLE',
    'The webhook node did not hand this node the raw body. Turn on Raw Body.');
}

const sigHeader = String(headers['x-hub-signature-256'] || '');
if (!sigHeader.startsWith('sha256=')) {
  return refuse(401, 'SIGNATURE_HEADER_MISSING', 'No X-Hub-Signature-256 on the request.');
}
if (!sameString(sigHeader, 'sha256=' + hmacHex(Buffer.from(APP_SECRET, 'utf8'), raw))) {
  return refuse(401, 'SIGNATURE_MISMATCH',
    'X-Hub-Signature-256 did not match an HMAC-SHA256 of the raw body. Nothing was written.');
}

let payload;
try { payload = JSON.parse(raw.toString('utf8')); }
catch (e) { return refuse(400, 'BODY_NOT_JSON', 'Signature verified but the body is not JSON.'); }

const out = [];
for (const entry of (payload.entry || [])) {
  for (const ch of (entry.changes || [])) {
    const v = ch.value || {};
    const pnid = String((v.metadata || {}).phone_number_id || '');
    const contacts = v.contacts || [];
    for (const m of (v.messages || [])) {
      const wa = String(m.from || '');
      const contact = contacts.find(c => String(c.wa_id || '') === wa) || {};
      const ts = Number(m.timestamp || 0);
      const id = String(m.id || '');
      const measurable = ts > 0 && id !== '' && pnid !== '';
      out.push({ json: {
        verdict: measurable ? 'ACCEPT' : 'ACCEPT_UNMEASURABLE',
        respond_status: 200, respond_text: 'ok',
        reason_code: measurable ? 'SIGNATURE_VERIFIED' : 'MESSAGE_NOT_MEASURABLE',
        raw_source,
        phone_number_id: pnid,
        waba_id: String(entry.id || ''),
        customer_wa_id: wa,
        customer_phone_digits: wa.replace(/[^0-9]/g, ''),
        customer_name: String((contact.profile || {}).name || ''),
        message_id: id,
        message_kind: String(m.type || 'text'),
        occurred_at: measurable ? new Date(ts * 1000).toISOString() : null,
        text: m.text ? String(m.text.body || '') : '',
        origin_verified: 'hmac_sha256_x_hub'
      } });
    }
  }
}
if (!out.length) {
  return [{ json: {
    verdict: 'ACCEPT_NO_MESSAGE', respond_status: 200, respond_text: 'ok',
    reason_code: 'NO_INBOUND_MESSAGE_IN_DELIVERY', wrote_nothing: true, raw_source } }];
}
return out;

/* What this node may and may not decide.
 *
 * MAY: whether this message is a fresh request to visit, or the customer
 * picking one of the times NEXUS already offered them.
 * MAY NOT: which time they meant. If the reply does not name an offered slot
 * by its number, the slot list is sent again. Guessing "they probably meant
 * the first one" is how a customer is told they are booked for a time they
 * never agreed to.
 *
 * TEST_DRIVE is the intent nexus_classify_message_intent (NX973) produces for
 * a customer asking to come in: it covers "test drive", "can i see", "visit",
 * "showroom", "appointment", "book a slot", "kab aa sakta". There is NO
 * APPOINTMENT intent in the classifier. TEST_DRIVE is the nearest honest one
 * and it is the one this workflow keys on.
 */
const cls  = $('Classify The Message').item.json || {};
const msg  = $('Verify Or Refuse').item.json || {};
const tid  = ($('Resolve Tenant From Phone Number ID').item.json || {}).tenant_id || null;
const cid  = ($('Find Customer In This Dealership').item.json || {}).id || null;

const row = $json && $json.appointment_id ? $json : null;
const slots = row && Array.isArray(row.offered_slots) ? row.offered_slots : [];
const text = String(msg.text == null ? '' : msg.text).trim();
const intent = String(cls.intent || 'UNKNOWN');

let step = 'NOT_A_BOOKING_MESSAGE';
let chosen_slot = null;
let chosen_index = null;
let why = 'Intent ' + intent + ' is not a request to visit the showroom.';

if (row && slots.length) {
  const m = text.match(/^\s*(?:option\s*)?([1-9])\b/i);
  const idx = m ? Number(m[1]) - 1 : -1;
  if (idx >= 0 && idx < slots.length) {
    step = 'CONFIRM';
    chosen_slot = slots[idx];
    chosen_index = idx;
    why = 'The customer replied with the number of a slot NEXUS actually offered.';
  } else if (intent === 'TEST_DRIVE') {
    step = 'REOFFER_UNREADABLE';
    why = 'An offer is open and the customer is still talking about visiting, but this message does not name one of the offered times. NEXUS will not pick one for them.';
  } else {
    why = 'An offer is open but this message neither picks a slot nor is about visiting.';
  }
} else if (intent === 'TEST_DRIVE') {
  step = 'REQUEST';
  why = 'Classified TEST_DRIVE by nexus_classify_message_intent, which is the classifier value for a customer asking to come in.';
}

return [{ json: {
  step, why, chosen_slot, chosen_index,
  intent,
  reason_codes: cls.reason_codes || [],
  tenant_id: tid,
  customer_id: cid,
  customer_wa_id: msg.customer_wa_id || null,
  customer_name: msg.customer_name || null,
  message_id: msg.message_id || null,
  message_text: text,
  open_appointment_id: row ? row.appointment_id : null,
  open_offered_slots: slots
} }];

/* THESE TIMES ARE ARBITRARY AND NX995 SAYS SO.
 *
 * NX995 has no capacity model: it does not know showroom opening hours, who is
 * on shift, or that Friday afternoon is prayer time. It will accept 03:00 on a
 * Saturday if somebody types it. This node therefore does not pretend to pick
 * a good time -- it picks three fixed daytime slots on the next two days and
 * the STATUS file says out loud that they are not checked against any diary.
 *
 * Asia/Dubai is UTC+04:00 all year and has no daylight saving, so the offset
 * is a constant rather than a lookup.
 */
const DUBAI_OFFSET_MS = 4 * 60 * 60 * 1000;
const now = Date.now();

function dubaiSlot(dayOffset, hour) {
  const shifted = new Date(now + DUBAI_OFFSET_MS);
  shifted.setUTCHours(0, 0, 0, 0);
  const ms = shifted.getTime() + (dayOffset * 86400000) + (hour * 3600000) - DUBAI_OFFSET_MS;
  return new Date(ms);
}

const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function dubaiLabel(d) {
  const w = new Date(d.getTime() + DUBAI_OFFSET_MS);
  const hh = String(w.getUTCHours()).padStart(2, '0');
  const mm = String(w.getUTCMinutes()).padStart(2, '0');
  return DAYS[w.getUTCDay()] + ' ' + w.getUTCDate() + ' ' + MONTHS[w.getUTCMonth()] + ', ' + hh + ':' + mm;
}

const candidates = [dubaiSlot(1, 11), dubaiSlot(1, 16), dubaiSlot(2, 11)]
  .filter(d => d.getTime() > now + 60000);

if (!candidates.length) {
  throw new Error('APPOINTMENT_NO_FUTURE_SLOT_COULD_BE_BUILT: every proposed slot computed to a time in the past, and nexus_appointment_offer_slots refuses a past slot. Nothing was offered.');
}

const upstream = $('Decide The Booking Step').item.json;
const appt = $json;

return [{ json: {
  appointment_id: appt.appointment_id,
  tenant_id: upstream.tenant_id,
  customer_wa_id: upstream.customer_wa_id,
  slots_iso: candidates.map(d => d.toISOString()),
  slots_labels: candidates.map(dubaiLabel),
  offer_text: 'Thanks for getting in touch. I can put you down for a showroom visit. Which of these suits you?\n'
    + candidates.map((d, i) => (i + 1) + ') ' + dubaiLabel(d)).join('\n')
    + '\n\nAll times are Dubai time. Reply with just the number. Nothing is held until you pick one.'
} }];

/* Reached only when NX995 REFUSED a write: a double booking, a past slot, an
 * illegal transition, a customer or vehicle belonging to another dealership.
 * The database's own sentence is carried through to the operator log, and the
 * customer gets a short true one. The word "booked" appears nowhere below.
 */
function dig(o, depth) {
  if (o == null || depth > 6) return null;
  if (typeof o === 'string') return o;
  if (typeof o !== 'object') return null;
  const keys = ['message', 'msg', 'error_description', 'details', 'detail', 'hint', 'description'];
  for (const k of keys) {
    if (typeof o[k] === 'string' && o[k].trim()) return o[k];
  }
  for (const k of ['error', 'response', 'body', 'cause', 'json', 'data', 'context']) {
    const v = dig(o[k], depth + 1);
    if (v) return v;
  }
  return null;
}

const raw = $json || {};
const dbMessage = dig(raw, 0) || 'The database refused the write and gave no message that this node could read.';

let customerText;
if (/DOUBLE_BOOKING_REFUSED/.test(dbMessage)) {
  customerText = 'Sorry, that time has just been taken. Could you pick one of the other times, or tell me another day that works?';
} else if (/in the past|already gone/i.test(dbMessage)) {
  customerText = 'Sorry, that time has already passed so I could not hold it. Tell me another day that works and we will sort it out.';
} else if (/TRANSITION_REFUSED/.test(dbMessage)) {
  customerText = 'Sorry, something is not right with this booking on our side. Someone from the showroom will message you to sort it out.';
} else {
  customerText = 'Sorry, I could not hold that appointment. Someone from the showroom will message you to sort it out.';
}

const up = $('Decide The Booking Step').item.json || {};

return [{ json: {
  refused: true,
  db_message: dbMessage,
  refusal_text: customerText,
  tenant_id: up.tenant_id || null,
  customer_wa_id: up.customer_wa_id || null,
  appointment_id: up.open_appointment_id || null,
  message_id: up.message_id || null,
  step: up.step || null
} }];

/* Only reached when nexus_appointment_confirm RETURNED. If it had raised --
 * past time, illegal transition, double booking -- this node never runs and the
 * refusal path composes an honest message instead. The word "booked" is used
 * here and only here.
 *
 * What it still does NOT mean, per NX995's own comment: this visit is in no
 * calendar and no salesperson has been assigned, so nothing stops the same
 * slot being given to someone else by a human.
 */
const DUBAI_OFFSET_MS = 4 * 60 * 60 * 1000;
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function dubaiLabel(iso) {
  const w = new Date(new Date(iso).getTime() + DUBAI_OFFSET_MS);
  const hh = String(w.getUTCHours()).padStart(2, '0');
  const mm = String(w.getUTCMinutes()).padStart(2, '0');
  return DAYS[w.getUTCDay()] + ' ' + w.getUTCDate() + ' ' + MONTHS[w.getUTCMonth()] + ', ' + hh + ':' + mm;
}

const appt = $json;
const up = $('Decide The Booking Step').item.json;

if (String(appt.state) !== 'CONFIRMED') {
  throw new Error('APPOINTMENT_CONFIRM_DID_NOT_CONFIRM: nexus_appointment_confirm returned state ' + appt.state + ' instead of CONFIRMED. No confirmation message was composed, because telling a customer they are booked on anything other than a CONFIRMED row is the one thing this workflow must never do.');
}

return [{ json: {
  appointment_id: appt.appointment_id,
  tenant_id: up.tenant_id,
  customer_wa_id: up.customer_wa_id,
  starts_at: appt.starts_at,
  confirmation_text: 'You are booked in for ' + dubaiLabel(appt.starts_at) + ' (Dubai time). '
    + 'We will see you at the showroom. If anything changes, just reply here.'
} }];

/* The customer is still talking about coming in but did not name one of the
 * times we offered. The offer is re-sent verbatim rather than interpreted.
 */
const DUBAI_OFFSET_MS = 4 * 60 * 60 * 1000;
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
function dubaiLabel(iso) {
  const w = new Date(new Date(iso).getTime() + DUBAI_OFFSET_MS);
  const hh = String(w.getUTCHours()).padStart(2, '0');
  const mm = String(w.getUTCMinutes()).padStart(2, '0');
  return DAYS[w.getUTCDay()] + ' ' + w.getUTCDate() + ' ' + MONTHS[w.getUTCMonth()] + ', ' + hh + ':' + mm;
}
const up = $json;
const slots = (up.open_offered_slots || []).filter(s => new Date(s).getTime() > Date.now());

const body = slots.length
  ? 'Sorry, I did not catch which time you meant. Please reply with just the number:\n'
      + slots.map((s, i) => (i + 1) + ') ' + dubaiLabel(s)).join('\n')
      + '\n\nAll times are Dubai time. Nothing is held until you pick one.'
  : 'Sorry, the times I offered you have now passed and I do not have new ones to give you. '
      + 'Someone from the showroom will come back to you with fresh times.';

return [{ json: {
  tenant_id: up.tenant_id,
  customer_wa_id: up.customer_wa_id,
  appointment_id: up.open_appointment_id,
  reoffer_text: body,
  slots_still_valid: slots.length
} }];

const wa = $('Verify Or Refuse').first().json.customer_wa_id;
const tenant = $('Resolve Tenant From Phone Number ID').first().json.tenant_id;
throw new Error('APPOINTMENT_CUSTOMER_NOT_RECORDED: wa_id ' + wa + ' has no row in public.customer for dealership ' + tenant + '. NX995 attaches an appointment to a customer who already exists and refuses to create one, so NOTHING was booked. The customer row is created by the live inbound receiver recording this conversation; if it is missing, that receiver did not run for this message.');

/* Meta already has its 200 (the respond node ran first), so this throw costs no
 * retry storm. It costs a FAILED row via the workflow's Error Workflow, which is
 * how anyone finds out that NX995 refused a booking.
 */
const j = $('Explain The Refusal Honestly').first().json;
throw new Error('APPOINTMENT_WRITE_REFUSED at step ' + j.step + ' for wa_id ' + j.customer_wa_id + ': ' + j.db_message + ' -- NOTHING was booked and the customer was told so, not told it was booked.');
